#!/usr/bin/env bash
set -euo pipefail

# Run checks for the source layout being built.
if [[ -f apps/sweet/go.mod ]]; then
  go test ./apps/sweet/...
  go vet ./apps/sweet/...
elif [[ -f pkg/sweet/go.mod ]]; then
  go test ./pkg/sweet/...
  go vet ./pkg/sweet/...
elif [[ -f go.mod ]]; then
  go test ./...
  go vet ./...
else
  go test ./pkg/cli/... ./pkg/core/...
  go vet ./pkg/cli/... ./pkg/core/...
fi
